namespace { ULONGLONG ft(const FILETIME&v){ULARGE_INTEGER x;x.LowPart=v.dwLowDateTime;x.HighPart=v.dwHighDateTime;return x.QuadPart;} bool cpuReady=false;ULONGLONG oldIdle=0,oldKernel=0,oldUser=0; struct Sample{ULONG index;uint64_t in,out;std::wstring description;};std::map<ULONG,std::pair<uint64_t,uint64_t>> previous;std::chrono::steady_clock::time_point previousTime;bool netReady=false;std::wstring lower(std::wstring s){for(auto&c:s)c=(wchar_t)std::towlower(c);return s;}bool excluded(const std::wstring&s){static const wchar_t* words[]={L"virtual",L"vmware",L"hyper-v",L"loopback",L"bluetooth",L"vpn",L"tap",L"wsl",L"docker"};auto x=lower(s);for(auto*w:words)if(x.find(w)!=std::wstring::npos)return true;return false;} typedef int nvmlReturn_t;typedef struct nvmlDevice_st* nvmlDevice_t;typedef struct { unsigned int gpu; unsigned int memory; } nvmlUtilization_t;constexpr nvmlReturn_t NVML_SUCCESS=0;using PFN_nvmlInit=nvmlReturn_t(__cdecl*)(void);using PFN_nvmlDeviceGetHandleByIndex=nvmlReturn_t(__cdecl*)(unsigned int,nvmlDevice_t*);using PFN_nvmlDeviceGetUtilizationRates=nvmlReturn_t(__cdecl*)(nvmlDevice_t,nvmlUtilization_t*);HMODULE g_nvmlDll=nullptr;bool g_nvmlTried=false;bool g_nvmlReady=false;PFN_nvmlInit pInit=nullptr;PFN_nvmlDeviceGetHandleByIndex pGetHandle=nullptr;PFN_nvmlDeviceGetUtilizationRates pGetUtil=nullptr;bool initNvml(){if(g_nvmlTried)return g_nvmlReady;g_nvmlTried=true;const char* paths[]={"nvml.dll","C:\\Program Files\\NVIDIA Corporation\\NVSMI\\nvml.dll","C:\\Windows\\System32\\nvml.dll","C:\\Program Files\\NVIDIA Corporation\\NVSMI\\nvml.dll"};for(auto p:paths){g_nvmlDll=LoadLibraryA(p);if(g_nvmlDll)break;}if(!g_nvmlDll)return false;pInit=(PFN_nvmlInit)GetProcAddress(g_nvmlDll,"nvmlInit_v2");if(!pInit)pInit=(PFN_nvmlInit)GetProcAddress(g_nvmlDll,"nvmlInit");pGetHandle=(PFN_nvmlDeviceGetHandleByIndex)GetProcAddress(g_nvmlDll,"nvmlDeviceGetHandleByIndex_v2");if(!pGetHandle)pGetHandle=(PFN_nvmlDeviceGetHandleByIndex)GetProcAddress(g_nvmlDll,"nvmlDeviceGetHandleByIndex");pGetUtil=(PFN_nvmlDeviceGetUtilizationRates)GetProcAddress(g_nvmlDll,"nvmlDeviceGetUtilizationRates");if(!pInit||!pGetHandle||!pGetUtil)return false;g_nvmlReady=(pInit()==NVML_SUCCESS);return g_nvmlReady;} }
double getCpuTotal(){FILETIME i{},k{},u{};if(!GetSystemTimes(&i,&k,&u))return 0;auto I=ft(i),K=ft(k),U=ft(u);if(!cpuReady){cpuReady=true;oldIdle=I;oldKernel=K;oldUser=U;return 0;}auto idle=I-oldIdle,total=(K-oldKernel)+(U-oldUser);oldIdle=I;oldKernel=K;oldUser=U;if(!total)return 0;return std::clamp(100.0*(double)(total-std::min(idle,total))/(double)total,0.0,100.0);}
std::string getCpuModel(){HKEY key=nullptr;if(RegOpenKeyExW(HKEY_LOCAL_MACHINE,L"HARDWARE\\DESCRIPTION\\System\\CentralProcessor\\0",0,KEY_READ,&key)!=ERROR_SUCCESS)return "未知 CPU";DWORD type=0,size=0;if(RegQueryValueExW(key,L"ProcessorNameString",nullptr,&type,nullptr,&size)!=ERROR_SUCCESS||type!=REG_SZ||!size){RegCloseKey(key);return "未知 CPU";}std::vector<wchar_t>b(size/sizeof(wchar_t)+1,L'\0');if(RegQueryValueExW(key,L"ProcessorNameString",nullptr,&type,(BYTE*)b.data(),&size)!=ERROR_SUCCESS){RegCloseKey(key);return "未知 CPU";}RegCloseKey(key);int n=WideCharToMultiByte(CP_UTF8,0,b.data(),-1,nullptr,0,nullptr,nullptr);if(n<=1)return "未知 CPU";std::string s(n,'\0');WideCharToMultiByte(CP_UTF8,0,b.data(),-1,s.data(),n,nullptr,nullptr);s.pop_back();return s;}
std::string getGpuModel(){Microsoft::WRL::ComPtr<IDXGIFactory1>f;if(FAILED(CreateDXGIFactory1(IID_PPV_ARGS(&f))))return "未知显卡";for(UINT i=0;;++i){Microsoft::WRL::ComPtr<IDXGIAdapter1>a;if(f->EnumAdapters1(i,&a)==DXGI_ERROR_NOT_FOUND)break;DXGI_ADAPTER_DESC1 d{};if(FAILED(a->GetDesc1(&d))||(d.Flags&DXGI_ADAPTER_FLAG_SOFTWARE))continue;int n=WideCharToMultiByte(CP_UTF8,0,d.Description,-1,nullptr,0,nullptr,nullptr);if(n<=1)return "未知显卡";std::string s(n,'\0');WideCharToMultiByte(CP_UTF8,0,d.Description,-1,s.data(),n,nullptr,nullptr);s.pop_back();return s;}return "未知显卡";}
double getGpuUsage(){if(!initNvml())return -1.0;nvmlDevice_t dev=nullptr;if(pGetHandle(0,&dev)!=NVML_SUCCESS)return -1.0;nvmlUtilization_t u{};if(pGetUtil(dev,&u)!=NVML_SUCCESS)return -1.0;return (double)u.gpu;}
MemoryInfo getMemoryInfo(){MEMORYSTATUSEX s{};s.dwLength=sizeof(s);if(!GlobalMemoryStatusEx(&s)||!s.ullTotalPhys)return {};double total=s.ullTotalPhys/1073741824.0,used=std::max(0.0,total-s.ullAvailPhys/1073741824.0);return {total,used,used/total*100.0};}
NetInfo getNetInfo(){NetInfo r;PMIB_IF_TABLE2 t=nullptr;if(GetIfTable2(&t)!=NO_ERROR||!t)return r;std::vector<Sample> c;for(ULONG i=0;i<t->NumEntries;i++){auto&x=t->Table[i];if(x.OperStatus!=IfOperStatusUp||(x.Type!=IF_TYPE_ETHERNET_CSMACD&&x.Type!=IF_TYPE_IEEE80211)||excluded(x.Description))continue;c.push_back({x.InterfaceIndex,x.InOctets,x.OutOctets,x.Description});}auto now=std::chrono::steady_clock::now();double sec=netReady?std::chrono::duration<double>(now-previousTime).count():0;uint64_t best=0;const Sample*pick=nullptr;for(auto&x:c){auto it=previous.find(x.index);uint64_t d=it==previous.end()?0:(x.in>=it->second.first?x.in-it->second.first:0)+(x.out>=it->second.second?x.out-it->second.second:0);if(!pick||d>best){pick=&x;best=d;}}if(pick){auto it=previous.find(pick->index);if(netReady&&sec>0&&it!=previous.end()){if(pick->out>=it->second.second)r.upMbps=(pick->out-it->second.second)*8.0/sec/1e6;if(pick->in>=it->second.first)r.downMbps=(pick->in-it->second.first)*8.0/sec/1e6;}r.rawInBytes=pick->in;r.rawOutBytes=pick->out;}previous.clear();for(auto&x:c)previous[x.index]={x.in,x.out};previousTime=now;netReady=true;FreeMibTable(t);return r;}
